// Client-built workflow template: publishes the form values as a canonical
// Bloodbank envelope through the deployed G2 outbox. Nothing here is a
// secret: the demo header token comes from the deployment env.
const form = $input.first().json;
const note = String(form.note ?? '').trim();
const mood = String(form.mood ?? '').trim();
if (!note || !mood) {
  throw new Error('note and mood are required');
}
const id = require('crypto').randomUUID();
const ceType = 'bloodbank.studio.note.recorded';        // 4 tokens, canonical
const subject = 'bloodbank.evt.studio.note.recorded';   // 5 tokens
return [{json: {ok: true, event: {
  specversion: '1.0', id, source: 'urn:33god:aperture:g2-client',
  type: ceType, subject, time: new Date().toISOString(),
  datacontenttype: 'application/json',
  correlationid: id, causationid: id,
  producer: 'aperture-g2-client', service: 'studio', domain: 'studio',
  kind: 'event', ordering_key: 'studio:note',
  actor: {type: 'operator', agent_id: 'operator:studio-client', cli: null, provider: null, model: null},
  data: {note, mood, via: 'client-form-workflow'}
}}}];
